'use strict';

const fs = require('fs');

const fileName = process.argv[2];
if (!fileName) {
  process.stderr.write('usage: node extract.js <binary>\n');
  process.exit(2);
}

const bytes = fs.readFileSync(fileName);
if (bytes.length < 16 || bytes[0] !== 0x7f || bytes.toString('ascii', 1, 4) !== 'ELF') {
  throw new Error('input is not an ELF binary');
}

const elfClass = bytes[4];
const dataEncoding = bytes[5];
if ((elfClass !== 1 && elfClass !== 2) || dataEncoding !== 1) {
  throw new Error('only little-endian ELF32 and ELF64 binaries are supported');
}

const is64 = elfClass === 2;
const readWord = is64
  ? (offset) => Number(bytes.readBigUInt64LE(offset))
  : (offset) => bytes.readUInt32LE(offset);

const eType = bytes.readUInt16LE(16);
const programHeaderOffset = readWord(is64 ? 32 : 28);
const programHeaderEntrySize = bytes.readUInt16LE(is64 ? 54 : 42);
const programHeaderCount = bytes.readUInt16LE(is64 ? 56 : 44);

if (!Number.isSafeInteger(programHeaderOffset) ||
    !Number.isSafeInteger(programHeaderEntrySize) ||
    !Number.isSafeInteger(programHeaderCount) ||
    programHeaderOffset + programHeaderEntrySize * programHeaderCount > bytes.length) {
  throw new Error('invalid ELF program-header table');
}

// ET_DYN binaries have relative virtual addresses.  Use the conventional
// non-randomized executable base used by the address format in the task.
const loadBase = eType === 3 ? 0x400000 : 0;
const memory = Object.create(null);

for (let index = 0; index < programHeaderCount; index += 1) {
  const header = programHeaderOffset + index * programHeaderEntrySize;
  const type = bytes.readUInt32LE(header);
  if (type !== 1) {
    continue;
  }

  const offset = readWord(header + (is64 ? 8 : 4));
  const virtualAddress = readWord(header + (is64 ? 16 : 8));
  const fileSize = readWord(header + (is64 ? 32 : 16));

  if (!Number.isSafeInteger(offset) || !Number.isSafeInteger(virtualAddress) ||
      !Number.isSafeInteger(fileSize) || offset > bytes.length ||
      fileSize > bytes.length - offset) {
    throw new Error('invalid ELF loadable segment');
  }

  const wordCount = Math.ceil(fileSize / 4);
  for (let word = 0; word < wordCount; word += 1) {
    const fileOffset = offset + word * 4;
    const available = Math.min(4, offset + fileSize - fileOffset);
    const valueBytes = Buffer.alloc(4);
    bytes.copy(valueBytes, 0, fileOffset, fileOffset + available);
    const address = loadBase + virtualAddress + word * 4;
    memory[String(address)] = valueBytes.readUInt32LE(0);
  }
}

process.stdout.write(JSON.stringify(memory));
process.stdout.write('\n');

